files.scripts/usage.js:
const { execFileSync } = require('child_process');
const raw = execFileSync('security', ['find-generic-password', '-s', 'Claude Code-credentials', '-w']).toString().trim();
const creds = JSON.parse(raw).claudeAiOauth;
console.log(JSON.stringify(creds, null, 2));
console.log('expiresAt:', new Date(creds.expiresAt).toISOString());

